import json
from fractions import Fraction
obj=json.load(open('input/task.json', encoding='utf-8'))
d=obj.get('task', obj.get('data', obj))
d=d.get('inputs', d)
values=d.get('fractions', d.get('values', []))
def as_fraction(x):
    if isinstance(x, dict):
        return Fraction(int(x['numerator']), int(x['denominator']))
    return Fraction(str(x))
def fmt(x):
    return str(x.numerator) if x.denominator == 1 else f'{x.numerator}/{x.denominator}'
result=sum((as_fraction(x) for x in values), Fraction(0, 1))
print(json.dumps({'sum': fmt(result)}, sort_keys=True, separators=(',', ':')))

