import json
from fractions import Fraction
obj=json.load(open('input/task.json', encoding='utf-8'))
d=obj.get('task', obj.get('data', obj))
d=d.get('inputs', d)
values=d.get('ratios', d.get('values', []))
def as_fraction(x):
    if isinstance(x, dict):
        return Fraction(int(x['numerator']), int(x['denominator']))
    return Fraction(str(x))
def fmt(x):
    return str(x.numerator) if x.denominator == 1 else f'{x.numerator}/{x.denominator}'
if not values:
    raise ValueError('at least one ratio is required')
parsed=[as_fraction(x.get('value', x.get('ratio')) if isinstance(x, dict) else x) for x in values]
index=max(range(len(parsed)), key=lambda i: parsed[i])
print(json.dumps({'index': index, 'maximum': fmt(parsed[index])}, sort_keys=True, separators=(',', ':')))

