import json
from fractions import Fraction
obj=json.load(open('input/task.json', encoding='utf-8'))
d=obj.get('task', obj.get('data', obj))
d=d.get('inputs', d)
values=d.get('speeds_kmh', d.get('speeds', []))
def as_fraction(x):
    if isinstance(x, dict):
        return Fraction(int(x['numerator']), int(x['denominator']))
    return Fraction(str(x))
def fmt(x):
    return str(x.numerator) if x.denominator == 1 else f'{x.numerator}/{x.denominator}'
result=[]
for item in values:
    value=item.get('value', item.get('kmh')) if isinstance(item, dict) else item
    result.append(fmt(as_fraction(value)*Fraction(5, 18)))
print(json.dumps({'meters_per_second': result}, sort_keys=True, separators=(',', ':')))

